def curriculum(program,chapter,title,module,module_title,order):
 return dict(program=program,chapterId=chapter,chapterTitle=title,moduleId=module,moduleTitle=module_title,order=order)
def validate_textbook(l):
 t=l['textbook'];ja='\n'.join(p['ja'] for p in t['paragraphs'])
 assert 4<=len(t['vocabulary'])<=8,(l['id'],'vocabulary count')
 for w in t['vocabulary']:assert w.get('surface',w['word']) in ja,(l['id'],'vocabulary',w)
 for f in t['focus']:assert f['quote'] in ja,(l['id'],'focus',f)
 assert t['readingQuestions'] and all(p['zh'] for p in t['paragraphs'])
def main():
 foundation=read('foundation')
 assert len(F)==len(foundation)==12
 for i,l in enumerate(foundation,1):
  l['textbook']=F[l['id'].removeprefix('foundation-')];l['textbook']['title']='本文 · '+l['title'];l['textbook']['scene']='初学者的小场景：'+l['subtitle']
  l['curriculum']=curriculum('jlpt','n5','N5日语入门','n5-foundations','文字、发音与学习方法',i-1);validate_textbook(l)
 write('foundation',foundation)
 business=read('business');mapping={};order=0
 for ch,ct,mod,mt,slugs in GROUPS:
  for slug in slugs:order+=1;mapping['b-'+slug]=curriculum('business',ch,ct,mod,mt,order)
 assert len(B)==len(business)==len(mapping)==50
 for l in business:
  l['textbook']=B[l['id'].removeprefix('b-')];l['textbook']['title']='本文 · '+l['title'];l['textbook']['scene']='工作场景：'+l['speaking'][0]['task'];l['curriculum']=mapping[l['id']];validate_textbook(l)
 write('business',business)
 for kind in ['reading','listening']:
  lessons=read(kind)
  for i,l in enumerate(lessons,1):
   words,quote,explanation=INPUT[l['id']]
   if kind=='reading':ja='\n\n'.join(l['sections'][0]['body']);zh=l['sections'][0]['translation']
   else:ja=l['listening'][0]['script'];zh=l['listening'][0]['translation']
   l['textbook']={'title':'本文 · '+l['title'],'scene':l['subtitle'],'paragraphs':[{'ja':ja,'zh':zh}],'vocabulary':vocab(words),'focus':[{'quote':quote,'explanation':explanation}],'readingQuestions':[{'question':q['prompt'],'answer':q['options'][q['answer']]+'。'+q['explanation']} for q in l['quiz'][:2]]}
   if kind=='reading':l['textbook']['reusedSectionIndex']=0
   level=l['level'].lower();chapter_title={'N5':'N5日语入门','N4':'N4日常表达','N3':'N3语境理解','N2':'N2综合运用','N1':'N1深入理解'}[l['level']];l['curriculum']=curriculum('jlpt',level,chapter_title,level+'-'+kind,'篇章阅读' if kind=='reading' else '听力与听写',(900 if kind=='reading' else 1000)+i)
   validate_textbook(l)
  write(kind,lessons)
